ruleToc.chapterList:
-<js>
//获取卷名
jm=java.getString("@css:.fed-drop-tops a@text");

jm=String(jm).split(/\n/);

//获取分卷
sub=java.getElements("@css:.all_data_list").toArray();

for(var i=0;i<sub.length;i++){

